def count_divisors(limit, num):
    s = [0] * (num + 1)
    for i in range(1, limit + 1):
        for j in range(i, num + 1, i):
            s[j] += 1
    return s
def main():
    N, M, K = map(int, input().split())
    s_N = count_divisors(N, 10 ** 6)
    s_M = count_divisors(M, 10 ** 6)
    result = 0
    for k in range(1, K + 1):
        result += k * s_N[k] * s_M[k]
    print(result)
if __name__ == "__main__":
    main()

import math
T = int(input())
for cas in range(T):
    n = int(input())
    m = int(math.log(n, 2)) + 1
    A = list(map(int, input().split()))
    pos = {}
    nxt = [[n for i in range(m + 1)] for j in range(n)]
    for i in range(n - 1, -1, -1):
        if not (A[i] in pos):
            nxt[i][0] = n
        else:
            nxt[i][0] = pos[A[i]]
        pos[A[i]] = i
    for i in range(n - 1, -1, -1):
        for j in range(1, m + 1):
            if nxt[i][j - 1] + 1 < n:
                nxt[i][j] = nxt[nxt[i][j - 1] + 1][j - 1]
    Q = int(input())
    for q in range(Q):
        l, r = map(int, input().split())
        l, r = l - 1, r - 1
        x, ans = l, 0
        while x <= r:
            while x <= r and nxt[x][0] > r:
                x, ans = x + 1, ans + 1
            if x > r:
                break

            for i in range(m, -1, -1):
                if nxt[x][i] <= r:
                    x = nxt[x][i]
                    break
            x += 1
        print(ans)
